using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class ElsaMorante
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Che il segreto dell'arte sia qui? Ricordare come l'opera si è vista in uno stato di sogno, ridirla come si è vista, cercare soprattutto di ricordare. Ché forse tutto l'inventare è ricordare.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Grande civiltà di Napoli: la città più civile del mondo. La vera regina delle città, la più signorile, la più nobile. La sola vera metropoli italiana.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Lodiamo tutta la multiforme nazione dei nostri compagni animali, questo circo angelico in cui l'uomo può riconoscere, a testimonianza del suo rango perduto, la nobile infanzia dell'Eden.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Napoli è tante cose, e molti sono i motivi per cui la si può amare o meno, ma soprattutto Napoli è una grande capitale, ed ha una stupefacente capacità di resistere alla paccottiglia kitsch da cui è oberata, una straordinaria possibilità di essere continuamente altro rispetto agli insopportabili stereotipi che la affliggono.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Più di tutto al mondo amo i bambini, il mare e i gatti.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Solo chi ama conosce. Povero chi non ama!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Una delle possibili definizioni giuste di scrittore, per me sarebbe addirittura la seguente: un uomo a cui sta a cuore tutto quanto accade, fuorché la letteratura.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "È strano come l'Eternità si lasci captare piuttosto in un segmento effimero che in una continuità estesa.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Ma mi sarei vergognato di inginocchiarmi, o di fare altre simili cerimonie, o di pregare, anche solo col pensiero: quasi davvero io potessi credere che quella era la casa di Dio, e che Dio è in comunicazione con noi, seppure esiste!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La loro sola speranza, era di diventare le spose d'un eroe: di servirlo, di stemmarsi del suo nome, di essere la sua proprietà indivisa, che tutti rispettano; e di avere un bel figlio da lui, somigliante al padre.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Mio padre non scriveva mai lettere, non faceva mai sapere sue notizie, né mandava nessun saluto. Ed era favolosa per me la certezza che pure egli esisteva, e che ogni istante da me vissuto a Procida, lo viveva lui pure in chi sa quale paesaggio, in chi sa quale stanza, fra compagni stranieri che io consideravo gloriosi e beati solo perché stavano con lui (non dubitavo, difatti, che la frequentazione di mio padre fosse il titolo di aristocrazia più ambito per tutte le società umane).", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "il lavoro non è per gli uomini, è per i ciucciarelli. Anche una fatica, magari, può dar gusto qualche volta, purché non sia un lavoro. Una fatica oziosa può riuscire utile e simpatica, ma il lavoro, invece, è una cosa inutile, e mortifica la fantasia.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Ma vivere senza nessun mestiere è la miglior cosa: magari accontentarsi di mangiare pane solo, purché non sia guadagnato.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "A uno non basta la contentezza di essere un valoroso, se tutti quanti gli altri non sono uguali a lui, e non si può fare amicizia. Il giorno che ogni uomo avrà il cuore valoroso e pieno d'onore, come un vero re, tutte le antipatie saranno buttate a mare. E la gente non saprà più che farsene, allora, dei re. Perché ogni uomo, sarà re di se stesso.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Beh, il primo pensiero, il massimo di tutti, è questo: \"Non bisogna importarsene della morte!\"", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Impara: il sacrificio è la sola, vera perversione umana.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Almeno dalle altre femmine, uno può salvarsi, può scoraggiare il loro \"amore\"; ma dalla madre, chi ti salva?", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Ah, è un inferno essere amati da chi non ama né la felicità, né la vita, né se stesso, ma soltanto te!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "L'amore vero è così: non ha nessuno scopo e nessuna ragione, e non si sottomette a nessun potere fuorché alla grazia umana.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Una speranza, a volte, indebolisce le coscienze, come un vizio.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Però il suo pensiero non è giusto: perché io non sono ragazza, sono vedova, e una vedova, seppure s'incontra con qualcuno, non fa tanto peccato come una ragazza: meno assai!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "E così in eterno ogni perla del mare ricopia la prima perla, e ogni rosa ricopia la prima rosa.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Spesso certi nostri affetti, che presumiamo magnifici, addirittura sovrumani, sono, in realtà, insipidi; solo un'amarezza terrestre, magari atroce, può, come il sale, suscitare il sapore misterioso della loro profonda mescolanza! Per tutta la mia infanzia e fanciullezza, io avevo creduto di amare W. G.; e forse m'ingannavo. Soltanto adesso, forse, incominciavo ad amarlo. Mi accadeva qualcosa di sorprendente, che certo in passato non avrei potuto credere, se me l'avessero predetta: W. G. mi faceva compassione.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "E immediatamente mi rendevo conto che in realtà non c'era stato nulla, né frastuoni né terremoti; era il dolore, che usava quegli artifici maligni per tenermi sveglio e non lasciarmi mai. Esso non mi lasciò mai, difatti, per tutta la giornata! Era la prima volta, da quando vivevo, che conoscevo veramente il dolore.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La speranza, tuttavia, s'era annidata ormai dentro di me come un parassita, che non lascia volentieri il suo nido.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Forse, la nostra natura ci porta a considerare i giochi dell'imprevisto più vani e arbitrari, troppo, di quel che sono. Così, ogni volta, per esempio, che in un racconto, o in un poema, l'imprevisto sembra giocare d'accordo con qualche segreta intenzione della sorte, noi volentieri accusiamo lo scrittore di vizio romanzesco. E, nella vita, certi avvenimenti imprevisti, per se stessi naturali e semplici, ci appaiono, per la nostra disposizione del momento, straordinari o addirittura soprannaturali.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "In sostanza, io conoscevo la storia fino dai tempi degli antichi egiziani, e le vite degli eccellenti condottieri, e le battaglie di tutti i passati secoli. Ma dell'epoca contemporanea, non sapevo nulla. Anche quei pochi segnali dell'epoca presente che arrivavano all'isola, io li avevo appena intravisti senza nessuna attenzione. Non m'aveva incuriosito mai, l'attualità. Come fosse tutto cronaca ordinaria da giornali, fuori della Storia fantastica, e delle Certezze Assolute.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La sola ragione che ho avuta (di cui fossi consapevole) nel mettermi a raccontare la vita di Arturo, è stata (non rida) il mio antico e inguaribile desiderio di essere un ragazzo.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Le libertà non vengono date. Si prendono.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La camera a gas è l'unico punto di carità, nel campo di concentramento.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Ma il freddo e l'acqua diaccia che procurano i geloni, la canicola che affatica e fa sudare, l'ospedale e la prigione, la guerra e i coprifuochi; gli alleati che pagano bene e il magnaccia giovane che la mena e le piglia tutti i guadagni; e questo bel ragazzo che si sbronza volentieri e parla e si sbraccia e dà calci: e nel letto la massacra, però è \"bravo\", giacché poi le riversa ogni volta fino agli ultimi soldi delle sue tasche; tutti i beni e tutti i mali: la fame che fa cadere i denti, la bruttezza, lo sfruttamento, la ricchezza e la povertà, l'ignoranza e la stupidità... per Santina non sono né giustizia né ingiustizia. Sono semplici necessità infallibili, delle quali non è data ragione. Essa le accetta perché succedono, e le subisce senza nessun sospetto, come una conseguenza naturale dell'esser nati.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "L'umanità, per propria natura, tende a darsi una spiegazione del mondo, nel quale è nata. E questa è la sua distinzione dalle altre specie. Ogni individuo, pure il meno intelligente e l'infimo dei paria, fino da bambino si dà una qualche spiegazione del mondo. E in quella si adatta a vivere. E senza di quella, cadrebbe nella pazzia.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La natura è di tutti i viventi... era nata libera, aperta, e LORO l'hanno compressa e anchilosata per farsela entrare nelle loro tasche. Hanno trasformato il lavoro degli altri in titoli di borsa, e i campi della terra in rendite, e tutti i valori reali della vita umana, l'arte, l'amore, l'amicizia, in merci da comprare e intascare. I loro Stati sono delle banche di strozzinaggio, che investono il prezzo del lavoro e della coscienza altrui nei loro sporchi affari: fabbriche d'armi e di immondezza, intrallazzi rapine guerre omicide! Le loro fabbriche di \"beni\" sono dei lager maledetti di schiavi, a servizio dei loro profitti... Tutti i loro valori sono falsi, essi campano di surrogati... E gli Altri... Ma si può ancora credere in \"altri\" da contrapporre a LORO? Forse le LORO falsificazioni resteranno l'unico materiale della Storia futura. È qui forse il punto cruciale d'inversione senza rimedio, dove i calcolatori scientifici della Storia, anche i migliori, purtroppo, hanno sbagliato il conto (la prognosi infausta del Potere, si capisce, viene rimossa da chi, dentro il pugno chiuso della rivoluzione, nasconde la stessa piaga infetta del Potere, negandone la malignità)! Si diagnosticava il male borghese come sintomatico di una classe (e dunque, soppressa la classe, guarito il male)! mentre invece il male borghese è la degenerazione cruciale, eruttiva, dell'eterna piaga maligna che infetta la Storia... è un'epidemia de pestilensia... E la borghesia segue la tattica della terra bruciata. Prima di cedere il potere, avrà impestato tutta la terra, corrotto la coscienza totale fino al midollo. E così, per la felicità non c'è più speransa. Ogni rivoluzione è già persa!", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Erano dei ciechi, guidati da ciechi e alla guida di altri ciechi, e non se ne accorgevano... Si ritenevano dei giusti – in perfetta buona fede! – e nessuno li smentiva in questo loro abbaglio.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Gli animali, come tutti i paria, sono talora ispirati da un genio quasi divino...", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "La Storia, si capisce, è tutta un'oscenità fino dal principio.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Si sa che la fabbrica dei sogni spesso interra le sue fondamenta fra i tritumi della veglia o del passato.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Sebbene io non abbia ancora vissuto un numero d'anni sufficiente per poterlo credere, sono quasi certa di essere stata io, quella ragazzina.", Author = "Elsa Morante" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Elsa_Morante", Text = "Chi fugge per amore non può trovar quiete nella solitudine.", Author = "Elsa Morante" },
        };
    }
}